362:     /**
363:      * @param baseClass never null
364:      * @param annotationClass never null
365:      * @return never null, sorted by type (fields before methods), then by {@link AlphabeticMemberComparator}.
366:      */
367:     public static List<Member> getAllMembers(Class<?> baseClass, Class<? extends Annotation> annotationClass) {
368:         var clazz = baseClass;
369:         Stream<Member> memberStream = Stream.empty();
370:         while (clazz != null) {
371:             var fieldStream = Stream.of(clazz.getDeclaredFields())
372:                     .sorted(alphabeticMemberComparator);
373:             var methodStream = Stream.of(clazz.getDeclaredMethods());
374: 
375:             for (var implementedInterface : clazz.getInterfaces()) {
376:                 methodStream = Stream.concat(methodStream, Arrays.stream(implementedInterface.getMethods()));
377:             }
378:             methodStream = methodStream.sorted(alphabeticMemberComparator);
379:             memberStream = Stream.concat(memberStream, Stream.concat(fieldStream, methodStream));
380:             clazz = clazz.getSuperclass();
381:         }
382:         return memberStream
383:                 .filter(member -> ((AnnotatedElement) member).isAnnotationPresent(annotationClass) && !member.isSynthetic())
384:                 .distinct().collect(Collectors.toList());
385:     }
