388:     public static Class<? extends Annotation> extractAnnotationClass(Member member,
389:             Class<? extends Annotation>... annotationClasses) {
390:         Class<? extends Annotation> annotationClass = null;
391:         for (var detectedAnnotationClass : annotationClasses) {
392:             if (((AnnotatedElement) member).isAnnotationPresent(detectedAnnotationClass)) {
393:                 if (annotationClass != null) {
394:                     throw new IllegalStateException("The class (" + member.getDeclaringClass()
395:                             + ") has a member (" + member + ") that has both a @"
396:                             + annotationClass.getSimpleName() + " annotation and a @"
397:                             + detectedAnnotationClass.getSimpleName() + " annotation.");
398:                 }
